package com.neoms;

import jakarta.servlet.http.HttpSession;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static com.neoms.Engine.*;

@RestController @RequestMapping("/api")
public class Api {
    final Store db;final Engine engine;final Seed seed;final Path uploadDir;final boolean demo;
    Api(Store db,Engine engine,Seed seed,@Value("${neoms.upload-dir:./data/uploads}")String dir,@Value("${neoms.demo-enabled:true}")boolean demo){this.db=db;this.engine=engine;this.seed=seed;this.uploadDir=Path.of(dir).toAbsolutePath().normalize();this.demo=demo;}
    String user(HttpSession session){Object id=session.getAttribute("userId");if(id==null)throw new Unauthorized();return id.toString();}
    @GetMapping("/health") public Object health(){return m("status","UP","database",db.jdbc().queryForObject("SELECT 1",Integer.class));}
    @GetMapping("/auth/users") public Object users(){return db.jdbc().queryForList("SELECT id,username,display_name AS name,role_name AS role FROM neoms_users ORDER BY username");}
    @PostMapping("/auth/login") public Object login(@RequestBody Map<String,Object>p,HttpSession session,HttpServletRequest request){var rows=db.jdbc().queryForList("SELECT * FROM neoms_users WHERE username=?",s(p,"username"));require(!rows.isEmpty()&&new BCryptPasswordEncoder().matches(s(p,"password"),rows.getFirst().get("password_hash").toString()),"账号或密码错误");request.changeSessionId();session.setAttribute("userId",rows.getFirst().get("id"));return me(session);}
    @GetMapping("/auth/me") public Object me(HttpSession session){return db.read(user(session));}
    @PostMapping("/auth/logout") public Object logout(HttpSession session){session.invalidate();return m("ok",true);}
    @PostMapping("/auth/switch") public Object switchUser(@RequestBody Map<String,Object>p,HttpSession session){user(session);require(demo,"非环境不能切换身份");var person=db.read(s(p,"userId"));require(s(person,"kind").equals("people"),"示例用户不存在");session.setAttribute("userId",person.get("id"));return person;}
    @GetMapping("/bootstrap") public Object bootstrap(HttpSession session){user(session);var r=new LinkedHashMap<String,Object>();for(String k:Store.KINDS)r.put(k,db.list(k));r.put("now",engine.now());r.put("demoEnabled",demo);r.put("version",Optional.ofNullable(NeomsApplication.class.getPackage().getImplementationVersion()).orElse("dev"));return r;}
    @GetMapping("/entities/{kind}") public Object list(@PathVariable String kind,HttpSession session){user(session);return db.list(kind);}
    @PostMapping("/entities/{kind}") public Object create(@PathVariable String kind,@RequestBody Map<String,Object>p,HttpSession session){return engine.create(kind,p,user(session));}
    @PutMapping("/records/{id}") public Object edit(@PathVariable String id,@RequestBody Map<String,Object>p,HttpSession session){return engine.edit(id,p,user(session));}
    @PostMapping("/records/{id}/actions/{action}") public Object action(@PathVariable String id,@PathVariable String action,@RequestBody(required=false)Map<String,Object>p,HttpSession session){return engine.act(id,action,p==null?m():p,user(session));}
    @GetMapping("/records/{id}/history") public Object history(@PathVariable String id,HttpSession session){user(session);return db.history(id);}
    @GetMapping("/approvals/history") public Object approvalHistory(@RequestParam String kind,HttpSession session){user(session);require(Set.of("defects","workTickets","operationTickets").contains(kind),"请选择审批对象");var out=new ArrayList<Map<String,Object>>();for(var row:db.jdbc().queryForList("SELECT actor,action_name,happened_at,snapshot FROM neoms_history WHERE kind=? ORDER BY id DESC",kind)){String action=row.get("action_name").toString();if(!(action.contains("通过")||action.contains("退回")||action.contains("作废")))continue;var item=db.parse(row.get("snapshot").toString());item.putAll(m("auditActor",row.get("actor"),"auditTime",row.get("happened_at"),"auditAction",action));out.add(item);}return out;}
    @DeleteMapping("/records/{id}") @Transactional public Object deleteDuty(@PathVariable String id,HttpSession session){String actor=user(session);var d=db.lock(id);require(s(d,"kind").equals("duties"),"仅年度职责记录支持删除");d.put("status","removed");var r=db.save(d);db.history(r,actor,"删除年度职责记录",engine.now());return r;}
    @GetMapping("/logs") public Object logs(@RequestParam String shiftId,HttpSession session){user(session);var shift=db.read(shiftId);require(s(shift,"kind").equals("shifts"),"请选择有效班次");var out=new ArrayList<Map<String,Object>>();for(var row:db.jdbc().queryForList("SELECT record_id,kind,actor,action_name,happened_at,snapshot FROM neoms_history WHERE happened_at>=? AND happened_at<? ORDER BY id DESC",s(shift,"startAt"),s(shift,"endAt"))){var snapshot=db.parse(row.get("snapshot").toString());if(!s(snapshot,"stationId").equals(s(shift,"stationId")))continue;out.add(m("recordId",row.get("record_id"),"kind",row.get("kind"),"actor",row.get("actor"),"action",s(snapshot,"kind").equals("notes")?s(snapshot,"description"):row.get("action_name").equals("创建记录")?"新增 "+s(snapshot,"name")+" · "+s(snapshot,"code"):row.get("action_name"),"time",row.get("happened_at")));}return out;}
    @PostMapping("/rules/preview") public Object preview(@RequestBody Map<String,Object>p,HttpSession session){user(session);return engine.preview(p);}
    @PostMapping("/roster/preview") public Object previewRoster(@RequestBody Map<String,Object>p,HttpSession session){return engine.roster(p,user(session),false);}
    @PostMapping("/roster/apply") public Object applyRoster(@RequestBody Map<String,Object>p,HttpSession session){return engine.roster(p,user(session),true);}
    @PostMapping("/roster/leave-preview") public Object leavePreview(@RequestBody Map<String,Object>p,HttpSession session){return engine.leave(p,user(session),false);}
    @PostMapping("/roster/leave") public Object leave(@RequestBody Map<String,Object>p,HttpSession session){return engine.leave(p,user(session),true);}
    @PostMapping("/clock") public Object clock(@RequestBody Map<String,Object>p,HttpSession session){require(demo,"非环境不能推进时钟");return engine.tick(s(p,"time"),user(session));}
    @PostMapping("/demo/reset") public Object reset(@RequestBody Map<String,Object>p,HttpSession session){user(session);require(demo&&s(p,"confirm").equals("RESET_DEMO"),"请明确确认重置本项目数据");seed.reset();return m("ok",true);}
    @GetMapping("/export") public ResponseEntity<String> export(HttpSession session){user(session);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=neoms-demo.json").contentType(MediaType.APPLICATION_JSON).body(db.stringify(m("demo",true,"time",engine.now(),"data",bootstrap(session))));}
    @PostMapping("/uploads") public Object upload(@RequestParam("file")MultipartFile file,HttpSession session)throws Exception{user(session);require(!file.isEmpty()&&file.getSize()<=8*1024*1024,"文件不能为空且须不超过8MB");String name=Objects.toString(file.getOriginalFilename(),"attachment");String ext=name.toLowerCase().replaceAll("^.*\\.","");require(Set.of("png","jpg","jpeg","webp","pdf","txt","csv").contains(ext),"仅支持图片、PDF、TXT和CSV附件");String id=UUID.randomUUID().toString(),disk=id+"."+ext;Files.createDirectories(uploadDir);Files.write(uploadDir.resolve(disk),file.getBytes());String mime=Set.of("png","jpg","jpeg","webp").contains(ext)?"image/"+(ext.equals("jpg")?"jpeg":ext):ext.equals("pdf")?"application/pdf":"text/plain";db.jdbc().update("INSERT INTO neoms_files VALUES(?,?,?,?)",id,name,mime,disk);return m("id",id,"name",name,"url","/api/uploads/"+id,"type","file");}
    @GetMapping("/uploads/{id}") public ResponseEntity<byte[]> file(@PathVariable String id,HttpSession session)throws Exception{user(session);var rows=db.jdbc().queryForList("SELECT * FROM neoms_files WHERE id=?",id);require(!rows.isEmpty(),"附件不存在");var f=rows.getFirst();var path=uploadDir.resolve(f.get("disk_name").toString()).normalize();require(path.startsWith(uploadDir),"附件路径无效");return ResponseEntity.ok().header("X-Content-Type-Options","nosniff").header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.inline().filename(f.get("original_name").toString(),StandardCharsets.UTF_8).build().toString()).contentType(MediaType.parseMediaType(f.get("media_type").toString())).body(Files.readAllBytes(path));}
    @PostMapping("/duties/import-preview") public Object importPreview(@RequestBody List<Map<String,Object>>rows,HttpSession session){user(session);return importRows(rows,false);}
    @PostMapping("/duties/import") @Transactional public Object importDuties(@RequestBody List<Map<String,Object>>rows,HttpSession session){user(session);return importRows(rows,true);}
    Object importRows(List<Map<String,Object>>rows,boolean save){require(rows.size()<=1000,"单次导入最多1000行");var out=new ArrayList<Map<String,Object>>();var keys=new HashSet<String>();for(var p:rows){var d=new LinkedHashMap<>(p);String result="通过";try{need(d,"year","stationId","dutyType","personId");require(s(d,"year").matches("20\\d{2}"),"年份无效");require(s(db.read(s(d,"stationId")),"kind").equals("stations"),"场站未匹配");require(s(db.read(s(d,"personId")),"kind").equals("people"),"人员未匹配");require(Set.of("工作签发人","工作负责人","工作许可人").contains(s(d,"dutyType")),"职责类型未匹配");String key=s(d,"year")+s(d,"stationId")+s(d,"dutyType")+s(d,"personId");require(keys.add(key),"文件内重复");require(db.list("duties").stream().noneMatch(x->(s(x,"year")+s(x,"stationId")+s(x,"dutyType")+s(x,"personId")).equals(key)),"已存在，跳过不覆盖");if(save)engine.create("duties",d,"系统导入");}catch(IllegalArgumentException e){result=e.getMessage();}d.put("result",result);out.add(d);}return out;}
    @GetMapping(value="/print/{id}",produces=MediaType.TEXT_HTML_VALUE) public String print(@PathVariable String id,@RequestParam(defaultValue="false")boolean draft,@RequestParam(required=false)Long historyId,HttpSession session){user(session);var d=db.read(id);if(historyId!=null){var histories=db.jdbc().queryForList("SELECT snapshot FROM neoms_history WHERE id=? AND record_id=?",historyId,id);require(!histories.isEmpty(),"历史版本不属于当前票据");d=db.parse(histories.getFirst().get("snapshot").toString());}require(Set.of("workTickets","operationTickets").contains(s(d,"kind")),"只有票据支持打印");require(draft||Set.of("executing","terminated").contains(s(d,"status")),"当前版本尚未完成签发 / 两次确认，仅可预览草稿");StringBuilder b=new StringBuilder("<!doctype html><html lang='zh-CN'><meta charset='UTF-8'><title>票据打印</title><style>body{font:14px 'Microsoft YaHei',sans-serif;margin:36px;color:#222}h1{text-align:center;font-size:24px}table{border-collapse:collapse;width:100%;margin:16px 0}th,td{border:1px solid #aaa;padding:10px;text-align:left}small{color:#666}.watermark{position:fixed;top:40%;left:25%;font-size:100px;color:#aaa4;transform:rotate(-25deg);z-index:-1}@media print{button{display:none}@page{size:A4;margin:15mm}}</style><button onclick='window.print()'>打印 / 另存为PDF</button>");if(draft)b.append("<div class='watermark'>草稿</div>");b.append("<h1>").append(h(s(d,"name"))).append(draft?"（草稿）":"").append("</h1><small>智慧运营中心 · 作业票据</small><table>");for(var kv:List.of(m("k","code","l","票号"),m("k","revision","l","版本"),m("k","status","l","当前阶段"),m("k","stationId","l","场站"),m("k","leaderId","l","工作负责人"),m("k","signedBy","l","签发人"),m("k","confirmedBy","l","负责人确认人"),m("k","permittedBy","l","工作许可人"),m("k","terminatedBy","l","终结登记人"),m("k","deviceName","l","设备"),m("k","description","l","工作内容"),m("k","plannedStart","l","计划开始"),m("k","plannedEnd","l","计划结束"),m("k","signedAt","l","签发时间"),m("k","confirmedAt","l","负责人确认时间"),m("k","permittedAt","l","许可人许可时间"),m("k","terminatedAt","l","终结时间")))b.append("<tr><th>").append(kv.get("l")).append("</th><td>").append(h(printValue(d,s(kv,"k")))).append("</td></tr>");b.append("</table>");for(String key:List.of("measures","items","hazards","processRecords")){b.append("<h2>").append(switch(key){case "measures"->"安全措施";case "items"->"操作项目";case "hazards"->"危险点与预控";default->"过程记录";}).append("</h2><table>");for(var row:items(d,key))b.append("<tr><td>").append(h(s(row,"group")+" "+s(row,"name")+s(row,"analysis")+s(row,"risk")+s(row,"type"))).append("</td><td>").append(h(s(row,"measures")+s(row,"description")+s(row,"result")+extraText(row))).append("</td><td>").append(h(s(row,"executedAt")+s(row,"time"))).append("</td></tr>");b.append("</table>");}if(d.get("termination") instanceof Map<?,?> term)b.append("<h2>终结补录</h2><p>").append(h(extraText((Map<String,Object>)term)+" "+Objects.toString(term.get("description"),""))).append("</p>");return b.append("</html>").toString();}
    String printValue(Map<String,Object>d,String key){String value=s(d,key);if(value.isBlank())return "—";if(key.equals("status"))return switch(value){case "draft"->"草稿";case "returned"->"已退回";case "pendingSign"->"待签发";case "pendingConfirm"->"待负责人确认";case "pendingPermit"->"待许可人许可";case "executing"->"执行中 / 待终结";case "terminated"->"已终结";case "void"->"已作废";default->value;};if(key.endsWith("Id")||key.endsWith("By")){try{return s(db.read(value),"name");}catch(IllegalArgumentException ignored){return value;}}return value;}
    String extraText(Map<String,Object>d){var titles=m("oldLeaderId","原负责人","newLeaderId","新负责人","oldMemberIds","原成员","newMemberIds","新成员","eventAt","实际发生时间","approvalAt","批准时间","approvedBy","批准人","validUntil","延期有效期","trialContent","试运行范围","restorationState","恢复状态","tagLockNumbers","挂牌上锁编号","isolationState","隔离状态","workEndAt","工作结束","ticketEndAt","票据终结","guardianId","监护人","siteRestored","现场恢复","personnelWithdrawn","人员撤离","riskAcknowledged","危险点确认","removedGroundLines","拆除接地线组数","openedGroundSwitches","拉开接地刀闸数");StringBuilder text=new StringBuilder();for(var field:titles.entrySet()){if(!d.containsKey(field.getKey()))continue;Object v=d.get(field.getKey());String value=v instanceof List<?>?ids(d,field.getKey()).stream().map(x->{try{return s(db.read(x),"name");}catch(IllegalArgumentException e){return x;}}).collect(java.util.stream.Collectors.joining("、")):v instanceof Boolean b?b?"已确认":"未确认":printValue(d,field.getKey());text.append("；").append(field.getValue()).append("：").append(value);}return text.toString();}
    static String h(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    static class Unauthorized extends RuntimeException{}
    @ExceptionHandler(Unauthorized.class) @ResponseStatus(HttpStatus.UNAUTHORIZED) public Object unauthorized(){return m("message","请先登录");}
    @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) @ResponseStatus(HttpStatus.BAD_REQUEST) public Object invalid(RuntimeException e){return m("message",e.getMessage());}
    @ExceptionHandler(Exception.class) @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR) public Object error(Exception e){org.slf4j.LoggerFactory.getLogger(Api.class).error("业务请求失败",e);return m("message","服务处理失败，请检查日志并重试");}
}
